-- Reviewed batch 15 for 2027 (universities, vocational school, language school).
-- Applied 2026-11-05 via scripts/apply-reviewed-sync-2027-consolidated.cjs.
-- Kept as the auditable SQL equivalent; running it again is idempotent only against rows that
-- already exist remotely (the guard below aborts if any target slug is missing).
-- Sources and limitations: docs/REDESIGN-AND-DATA.md and data/school-reviews.ts.
-- Controlled sync: 18 University, 1 VocationalSchool and 1 LanguageSchool record, upsert by slug;
-- no DELETE, bulk import, or schema changes.
BEGIN;
-- University: 18 reviewed record(s) — upsert only, no DELETE.
DO $$ BEGIN
  IF (SELECT count(*) FROM "University" WHERE slug IN ('utokyo', 'hiroshima-u', 'kobe-u', 'hitotsubashi', 'nitech', 'sophia', 'meiji', 'rikkyo', 'hosei', 'doshisha', 'tus', 'shibaura', 'denki', 'aoyama', 'chuo', 'kinki', 'nihon', 'toyo')) <> 18 THEN
    RAISE EXCEPTION 'Expected reviewed University records are missing; no updates applied';
  END IF;
END $$;
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'utokyo', '东京大学', '東京大学', 'national', '日本第1·QS世界28', '东京都文京区', '本科642,960日元/年；修士535,800日元/年（法科大学院除外）', '3.5+/4.0', '文科N1 150+ / 理科N2+', 'TOEFL iBT 100+ / IELTS 7.0+', '日本最高学府，所有学科领域均为世界顶级，英语学位项目须按研究科确认；PEAK已结束招生', '多数研究科接受研究生，需教授内诺。入学料84,600円，授课料28,900円/月（346,800円/年）。EEIS电气电子系guidebook直接标注教授受入状态。', '大学院：各研究科独立笔试+面试+书类选考。学部：外国学校卒业学生特别选考（书类+小论文+学力试验+面试），全科类合计约20-30名合格/年。', 'PEAK最后一届为2026年9月入学，申请已关闭，不招收2027新生。其他英语项目请查看各院系官网。', 'https://www.u-tokyo.ac.jp/en/prospective-students/', '["日本排名第一","研究经费全国第一","SGU项目丰富","产学合作最强","留学生支援完善"]'::jsonb, '[{"name":"情报理工学系研究科","level":"graduate","description":"计算机科学、数理情报、电子情报、知能机械、创造情报学5专攻","features":["CS ranking日本1位","夏季+冬季入试","TOEFL必须","竞争率38%-47%"]},{"name":"工学系研究科","level":"graduate","description":"社会基盘、建筑、机械、航空宇宙、电气、物理工学等18专攻，IME英语项目","features":["18专攻","IME英语项目","隈研吾教授在籍"]},{"name":"经济学研究科","level":"graduate","description":"经济学/经营学/金融学，UTIPE英语项目，2025年改革","features":["神取道宏教授(博弈论)","UTIPE英语项目","GRE必须"]},{"name":"理学系研究科","level":"graduate","description":"物理学、化学、生物科学，约80实验室","features":["诺贝尔奖辈出","国际卓越研究大学","全英授课可选"]},{"name":"文科一类(法学部)","level":"undergraduate","description":"法学部第1-3类，前期课程2年+后期课程2年","features":["文科一类→法学部","进学振分制度","留学生枠极少"]},{"name":"理科一类(工学部)","level":"undergraduate","description":"工学部16学科+理学部10学科","features":["理科一类→工/理学部","日本最强理工系"]}]'::jsonb, '["冲刺日本最高学府","研究志向","TOP学霸"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'hiroshima-u', '广岛大学', '広島大学', 'national', '日本第10·QS世界338', '广岛县东广岛市', '官网现行：学部（日间）535,800日元/年、大学院研究科535,800日元/年、法科大学院804,000日元/年；入学料282,000日元（法科大学院同额）。2027年度起授课费缴纳方式改为账户转账。', '未核实（官网未公开统一GPA门槛）', '未核实（官网未公开统一日语等级门槛，按各学部/研究科要项）', 'IGS英语本科：TOEFL iBT 72以上／IELTS 5.5以上（选拔方式A/B/D）；方式C为TOEFL iBT 44以上／IELTS 4.0以上', 'IGS英语本科2027年4月入学已公布四种选拔方式与定员（A 4名、B 10名、C 6名、D 限员）；官网有HU-IAAS事前审查与UCARO出愿流程。', '官网：研究生（含外国人）入学料84,600日元，授课料29,700日元/月。是否需教授内诺与学历认证材料按各研究科要项确认。', 'IGS本科：2027年采用四种选拔（A海外7月、B海外11月、C广岛校内11月、D广岛校内2月），A/B为线上英语面试，C/D需到东广岛校区面试。其余学部与研究科按各自要项。', NULL, 'https://www.hiroshima-u.ac.jp/en/igs/admissions_2027', '["IGS英语本科（2027年4月入学）","HU-IAAS事前审查","UCARO在线出愿","法科大学院另计学费"]'::jsonb, '[{"name":"IGS英语本科（国际全球研究）","level":"undergraduate","description":"2027年4月1日入学，无9/10月入学。四种选拔方式合计定员约20名（D为限员）。","features":["全英文","2027年4月入学","四种选拔方式"]},{"name":"人间社会科学研究科","level":"graduate","description":"官网列示的研究科之一；具体专攻与出愿条件按研究科要项确认。","features":["需按研究科要项确认"]},{"name":"先进理工系科学研究科","level":"graduate","description":"官网列示的研究科之一；具体专攻与出愿条件按研究科要项确认。","features":["需按研究科要项确认"]},{"name":"情报科学部","level":"undergraduate","description":"官网学部列表中列有情报科学部（School of Informatics and Data Science）。","features":["学部"]}]'::jsonb, '["广岛/中国地区","IGS英语本科路径","愿意按研究科要项逐项确认"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'kobe-u', '神户大学', '神戸大学', 'national', '日本第11·QS世界400+', '兵库县神户市', '官网令和8年度：学部535,800日元/年、大学院研究科（法学研究科实务法律专攻除外）535,800日元/年、法学研究科实务法律专攻804,000日元/年；入学料282,000日元。授课费分前期（4月）、后期（10月）两期缴纳。', '未核实（官网未公开统一GPA门槛）', '未核实（官网未公开统一日语等级门槛）', '未核实（官网未公开统一英语分数门槛；英语授课项目各自规定）', '官网公开8个英语授课项目：KIMAP（法学/经济学/经营学）、理学、保健学ICHS、医学研究、农学Kobe Global Graduate Program、国际协力研究科硕士/博士课程。', '官网：研究生入学料84,600日元，授课料29,700日元/月。是否需教授内诺按各研究科要项确认。', '本科与大学院均由各学部/研究科分别实施入学考试；2027年度（令和9年度）入试日程在神户大学受験生ナビ公布。', NULL, 'https://www.kobe-u.ac.jp/en/academics/courses-in-english/', '["经营学部・经营学研究科","海洋政策科学部","8个英语授课项目","神户都市圈"]'::jsonb, '[{"name":"KIMAP in Management（经营学研究科）","level":"graduate","description":"经营学研究科英语授课硕士项目。","features":["英语授课","硕士"]},{"name":"KIMAP in Economics（经济学研究科）","level":"graduate","description":"经济学研究科英语授课硕士项目。","features":["英语授课","硕士"]},{"name":"KIMAP in Global Business Law（法学研究科）","level":"graduate","description":"法学研究科英语授课硕士项目。","features":["英语授课","硕士"]},{"name":"英语授课硕士（国际协力研究科）","level":"graduate","description":"国际协力研究科设英语授课硕士与博士课程。","features":["英语授课","硕士/博士"]},{"name":"经营学部","level":"undergraduate","description":"官网列示学部之一。","features":["学部"]},{"name":"海洋政策科学部","level":"undergraduate","description":"官网列示学部之一。","features":["学部"]}]'::jsonb, '["经营/商学志向","关西圈留学","英语授课硕士路径"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'hitotsubashi', '一桥大学', '一橋大学', 'national', '日本第10·QS世界530+', '东京都国立市', '官网2026年度表：2020年度以后入学者 学部授课费321,480日元/学期（年额642,960日元）；一般大学院生与2021年度以后入学的商学研究科学生同为321,480日元/学期；法科大学院402,000日元/学期。入学料282,000日元，学部检定料17,000日元、大学院30,000日元。', '未核实（官网未公开统一GPA门槛）', '未核实（官网未公开统一日语等级门槛）', '未核实（官网未公开统一英语分数门槛）', '官网列明社会科学系5学部（商学、经济学、法学、社会学、社会数据科学）与对应研究科；大学院设英语授课的专门职项目。', '官网：研究生检定料9,800日元、入学料84,600日元、授课料29,700日元/月。是否需教授内诺按各研究科要项确认。', '官网说明大学院设英语授课的专门职项目；各研究科出愿方式与考试内容按研究科要项确认，未公开统一门槛。', NULL, 'https://www.hit-u.ac.jp/eng/ryugaku/tuition.html', '["社会科学5学部","小规模精英教育","东京都国立市","英语授课专门职项目"]'::jsonb, '[{"name":"商学研究科","level":"graduate","description":"官网列示研究科之一；具体专攻与出愿条件按研究科要项确认。","features":["需按研究科要项确认"]},{"name":"经济学研究科","level":"graduate","description":"官网列示研究科之一；具体专攻与出愿条件按研究科要项确认。","features":["需按研究科要项确认"]},{"name":"法学研究科","level":"graduate","description":"官网列示研究科之一，含法科大学院。","features":["法科大学院"]},{"name":"社会学研究科","level":"graduate","description":"官网列示研究科之一。","features":["需按研究科要项确认"]},{"name":"言语社会研究科","level":"graduate","description":"官网列示研究科之一。","features":["需按研究科要项确认"]},{"name":"社会数据科学研究科","level":"graduate","description":"官网列示研究科之一。","features":["需按研究科要项确认"]},{"name":"商学部","level":"undergraduate","description":"官网列示学部之一。","features":["学部"]},{"name":"经济学部","level":"undergraduate","description":"官网列示学部之一。","features":["学部"]},{"name":"法学部","level":"undergraduate","description":"官网列示学部之一。","features":["学部"]},{"name":"社会学部","level":"undergraduate","description":"官网列示学部之一。","features":["学部"]}]'::jsonb, '["经济学/商学志向","社科类精英教育","东京留学","英语授课专门职项目"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'nitech', '名古屋工业大学', '名古屋工業大学', 'national', '国立工科系', '爱知县名古屋市', '官网留学生费用页：2026年度以后入学的学部生授课费642,960日元/年（321,480日元/学期）；大学院工学研究科博士前期课程2027年度以后入学者642,960日元/年，博士后期课程535,800日元/年。入学料282,000日元，检定料学部17,000日元、大学院30,000日元。', '未核实（官网未公开统一GPA门槛）', '未核实（官网未公开统一日语等级门槛）', '未核实（官网未公开统一英语分数门槛）', '官网公布授课费改定：学部2026年度起、博士前期课程2027年度起年额642,960日元；另公布2028年度起工学部私费外国人留学生选拔出愿资格将变更（2026-10-27公告）。', '官网：研究生检定料9,800日元、入学料84,600日元、授课料178,200日元/半年（356,400日元/年）。', '学部与大学院分别实施入学者选拔；2028年度（令和10年度）工学部私费外国人留学生选拔的出愿资格已公告将变更。具体日程按入试要项确认。', NULL, 'https://www.nitech.ac.jp/int/information/expense.html', '["授课费2026/2027年度改定","工学部6学科","博士前期19个program","2028年度留学生选拔资格变更"]'::jsonb, '[{"name":"工学部","level":"undergraduate","description":"生命・应用化学科、物理工学科、电气・机械工学科、情报工学科、社会工学科、创造工学教育课程。","features":["6学科","2026年度起授课费642,960日元/年"]},{"name":"大学院工学研究科 博士前期课程（工学专攻）","level":"graduate","description":"官网列19个program（生命・物质化学、软物质、环境陶瓷、材料功能、应用物理、电气电子、机械工学、网络、智能情报、媒体情报、情报数理、建筑・设计、环境都市、经营系统、未来通信、碳中和、医工学、创造工学、社会人创新）。","features":["19个program","2027年度起642,960日元/年"]},{"name":"大学院工学研究科 博士后期课程","level":"graduate","description":"官网设博士后期课程。","features":["博士后期"]}]'::jsonb, '["中部圈就职","制造业志向","工科专门方向"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'sophia', '上智大学', '上智大学', 'private', 'G5成员', '东京都千代田区', '2027：FLA首年约1,669,000日元、次年起1,442,000日元；SPSF首年约1,645,000日元、次年起1,442,000日元', '各项目书类审查，官网未公布统一GPA分数线', '英语授课本科的材料与语言条件按2027项目要项执行', 'FLA/SPSF要求TOEFL或IELTS，并提交SAT、ACT、IB或GCE A-level之一', '2027英语本科包含FLA、SPSF；理工学部Digital Green Technology计划于2027年4月启动', '部分研究科接受。', 'FLA 2027年4月首轮为2026-09-01至09-09，SPSF 2027年9月首轮为2026-11-11至12-04；均以项目要项为准。', NULL, 'https://adm.sophia.ac.jp/eng/admissions/', '["FLA全英文","SPSF全英文","DGTech 2027启动","书类审查"]'::jsonb, '[{"name":"国际教养学部（FLA）","level":"undergraduate","description":"BA in Liberal Arts；比较文化、社会研究、国际商务与经济等领域。","features":["4月/9月入学","英语授课","书类审查"]},{"name":"Sophia Program for Sustainable Futures（SPSF）","level":"undergraduate","description":"Journalism、Education、Sociology、Economics、Management、International Relations、Area Studies。","features":["仅9月入学","英语授课","书类审查"]},{"name":"Digital Green Technology（DGTech）","level":"undergraduate","description":"理工学部英语项目，覆盖应用化学、生命科学、机械、电气电子及跨学科领域，计划2027年4月启动。","features":["2027年4月","英语授课"]}]'::jsonb, '["新闻/媒体志向","英语路径(FLA)","国际关系","外语·国際系","环境/可持续发展"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'meiji', '明治大学', '明治大学', 'private', 'MARCH核心校', '东京都千代田区', '国际日本学部英文赛道2027年9月入学届：首期（2027学年）893,000日元（含入学金200,000）；2028学年全年度约1,373,500日元，2029学年约1,378,500日元，2030学年约1,413,500日元（末年含校友会费30,000）。本批未核对其余学部学费。', '英文赛道未设统一GPA门槛；须提交高中官方成绩单与评分准则说明。', '英文赛道入学时不要求日语能力，入学后不可切换至日语赛道；可选修SGJS开设的日语课程。', 'TOEFL iBT 80+（2026-01-20前旧制）或4.0+（2026-01-21起新band1-6）；或IELTS Academic（含机考）6.0+；或剑桥英语 B1-C2 综合169+；或纸质SAT阅读27+且写作与语言28+（Digital SAT不受理）；或ACT English 18+（ACT Online可）。考试日期限2025-02-18至2027-01-14的单场；不接受家考、MyBest、Super scoring；全员提交，无豁免。', '国际日本学部英文赛道为明治大学本科全英文学位项目，以英语与日语并用的视角研究日本文化与当代社会。', '部分研究科接受。', '2027年9月入学：资格审查邮件预审截止2027-01-04 23:59（JST）；网申+选拔费2027-02-04 15:00至02-17 14:59；文件与官方成绩2027-02-24 16:59前送达；注册号2027-05-06 15:00起可查；第一轮结果2027-05-13 10:00至05-19公布，第二轮在线面试2027-05-22，最终合格2027-06-08 10:00起公布，入学手续截止2027-06-29。选拔费35,000日元+系统使用费1,045日元（收款不退项见要项）。', 'SGJS英文赛道2026学年起停止4月入学、只设9月入学；2027届定员10名，不接收转学生；选拔为书类审查+在线面试两轮。', 'https://www.meiji.ac.jp/cip/english/undergraduate/nippon/englishtrack/admissions.html', '["SGJS英文赛道","仅9月入学","定员10人","入学不需日语","不限国籍"]'::jsonb, '[{"name":"国际日本学部 英文赛道（SGJS English Track）","level":"undergraduate","description":"全英文授课本科，以日本文化与社会为核心，选修课含日语授课课程；2026学年起停止4月入学，仅设9月入学，不接收转学生且学分不可转入。","features":["全英文授课","仅9月入学","定员10人","不支持转学"]}]'::jsonb, '["英文授课追求","日本文化·社会研究","希望兼顾日语选修"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'rikkyo', '立教大学', '立教大学', 'private', 'MARCH中上难度', '东京都豊岛区', 'PEACE 2027届（校方2027学年学费通知：与2026学年持平，实验实习费部分调整）：入学金200,000日元；年学费为国际商务法Global Program 1,271,000日元、异文化交流（ICC）1,178,000日元、GLAP 1,900,000日元。2027届首年合计（含第一、二期）约为：国际商务法1,474,500日元、ICC 1,391,500日元、GLAP 2,103,500日元（仅含2026学年估算，其他费用按规定另行收取约4%行政费）。ICC海外研修期间学费为939,000日元/年；GLAP所有在校生均参加长期留学，PEACE来源学生为可选（免学费，差旅住宿自付）。本批未核对其余学部学费。', '未设统一GPA门槛；须满足指南第5节指定高中资格条件(a)-(j)之一并提供官方证明。', '英文项目本身不设日语门槛；入学后语言课必修：法学政治学部与异文化交流学部 languages A/B 均为日语，GLAP为 Language A 英语 + Language B 日语。', '按高中资格设最低线（示例：IBDP 28/奖学金35；ATAR 79/85；SAT 1170或ACT 24，奖学金1250/26；A-Level 8分/11；新加坡A-Level 10/12；HKDSE 2024以前18与2024以后14；STPM 10.00；UYEC 18），未能满足英语子项时可用TOEFL iBT 94（新band4.5）或IELTS 6.5替代；不接受家考、MyBest、Superscore。', 'PEACE为异文化交流（ICC）、国际商务法（Global Program）与GLAP的全英文本科学位项目。', '部分研究科接受。', 'PEACE一般申请2027：4月入学2026-11-06起申请、11-20 15:00截止（含申请费缴纳），12-08发申请编号、2027-01-15 10:00发表；9月入学2027-01-18起申请、02-01 15:00截止，02-16编号、03-05 10:00发表；录取通知后一期学杂费缴纳分别于2027-01-22与03-12 15:00截止。申请费15,000日元+620日元手续费（仅供令和WEB系统信用卡缴费，不退还）。每项目名额为推荐制、一般申请、4月与9月入学四者的合计10人。', 'B.A.英文项目为PEACE（ICC、国际商务法、GLAP3个专攻）；NEXUS需指定高中协议，不开放一般申请。中国内地学生申请COE另行适用入国前结核筛查(JPETS)。', 'https://english.rikkyo.ac.jp/admission/peace-and-nexus.html', '["PEACE三项目","4月/9月双入学","两轮信审+面试","各项目名额10","官方直送成绩"]'::jsonb, '[{"name":"异文化交流学部 Intercultural Communication for Global Leadership","level":"undergraduate","description":"PEACE项目英语授课；2027年名额10（推荐制与一般申请合计，4月与9月入学合计）。","features":["英语授课","PEACE项目","名额10"]},{"name":"法学政治学部 国际商务法 Global Program","level":"undergraduate","description":"PEACE项目英语授课；2027年名额10（推荐制与一般申请合计，4月与9月入学合计）。","features":["英语授课","PEACE项目","名额10"]},{"name":"GLAP（Global Liberal Arts Program）","level":"undergraduate","description":"英语授课；入学后需要 Language A 英语 + Language B 日语；在校生均参加长期留学（PEACE来源为可选）。","features":["PEACE项目","名额10","留学必修"]},{"name":"NEXUS 项目","level":"undergraduate","description":"第一学期集中强化日语，第二学期起进入专业学部；仅面向与大学有学生接收协议的指定高中，不设开放申请。","features":["指定高中限定","日语强化","非PEACE流程"]}]'::jsonb, '["英文授课学位","跨文化交流与国际商务","广域教养（GLAP）"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'hosei', '法政大学', '法政大学', 'private', 'MARCH', '东京都千代田区/町田市', '2027届入学者学费（校方2027年度学费页，另有诸会费）：GIS首年1,632,000日元（含入学金240,000；第二学年及其后1,392,000日元/年）；IGESS、GBP、SCOPE首年各1,494,000日元（含入学金240,000；第二学年及其后1,254,000日元/年）。', '未设统一GPA门槛；资格按各项目最新指南要求。', '全英文授课；无需日语成绩。', 'GIS：TOEFL iBT 90+（2026-01-20前旧制）或5.0+（2026-01-21起新band）/IELTS 7.0+，或以英语为 IB Language A 并取得文凭；GBP、SCOPE：TOEFL iBT 80+（旧制）或4.0+（新band）/IELTS 6.0+；IGESS：必须提交TOEFL或IELTS（不设最低分数线）。家考、MyBest、IELTS Online/Indicator均不受理。', '四项全英文学位（GIS、GBP、SCOPE、IGESS）2027年秋季统一申请；一次书类审查加全员在线面试的两阶段选拔。', '部分研究科接受。', '2027年秋季（四项目统一日程）：申请期2027-02-22至03-05（网申首日10:00开始，书类须在截止日送达或（国内）邮戳）；第一轮结果2027-04-23，面试细节2027-05-07，Zoom连接测试05-12或05-13，在线面试05-16（SCOPE为05-15），结果2027-05-25，入学手续2027-05-25至06-15，入学日2027-09-16。选拔费35,000日元+1,100日元手续费，卡缴费不退；DAC低收入国可免（需在期首日前联系 ebdp-i@ml.hosei.ac.jp）。标准化成绩仅认 SAT（直送码3686）、ACT（0607）、IB文凭、或GCE A-Level（3科或2A+2AS合计4科）。', '2027年度起此前 Period I/II 合并为单一申请期，且第一轮通过者一律参加在线面试。', 'https://www.hosei.ac.jp/english/admissions/undergraduate/ebdp/', '["GIS/GBP/SCOPE/IGESS","2027年单一申请期","两阶段选拔","DAC低收入国可免选拔费"]'::jsonb, '[{"name":"GIS（Global and Interdisciplinary Studies）","level":"undergraduate","description":"文理与商学教养课程，含4月与9月入学；2027年秋季定员10名。","features":["4月/9月入学","同次书审","秋季定员10"]},{"name":"GBP（Global Business Program）","level":"undergraduate","description":"2027年9月入学，工商管理方向；共20名：面向持留学签证者10名+其他在留资格10名。","features":["9月入学","20名","改革后单一期"]},{"name":"SCOPE（Sustainability Co-creation Programme）","level":"undergraduate","description":"2027年9月入学，可持续发展方向（人类环境学部）；共20名：面向持留学签证者10名+其他在留资格10名。","features":["9月入学","20名","可持续领域"]},{"name":"IGESS（全球经济与社会科学研究所）","level":"undergraduate","description":"2027年9月入学，经济学方向（经济学部），一至三年级城市校区（Ichigaya）+后期多摩校区；30名。","features":["9月入学","30名","经济方向"]}]'::jsonb, '["全英文学位","文理教养 / 商学 / 可持续 / 经济方向"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'doshisha', '同志社大学', '同志社大学', 'private', '关关同立最上位', '京都市上京区', 'ILA 2027届（校方公布）：四年学年总均为1,194,000日元。首年含入学金200,000、学费824,000、设施费170,000；第二学年起学费1,024,000、设施费170,000；第四年另收校友会费，按学期分两期缴。第三年插入学首期合计774,000日元，第三学年1,348,000日元、第四学年1,148,000日元。申请费15,000日元（海外电子汇款需含2,500日元手续费，共17,500日元），缴后不退。', '官方未设统一硬性分数线；招生政策说明获批学生通常为IB 32+、Digital SAT 1300+、ACT 25+或三科GCE A-Level（视为参考而非硬线）。', '全英文授课；不要求JLPT成绩。', 'TOEFL iBT 85+（测试在2026-01-20前）或4.5+（2026-01-21起新band，code D680）；或IELTS Academic 6.5+（可UKVI/机考；Online与One Skill Retake不受理）；或Duolingo 120+；或ACT English 22+（code 9078，不收Superscore）；或Digital SAT EBRW 560+（code 7231，不收Superscore）；Home Edition与MyBest不受理。成绩限两年内；英语母语或接受12年英语授课者可豁免。', '所设面向约50名/年的国际教养课程（三方向集中），小规模、讨论型课堂，京都双校区。', '部分研究科接受研究生。', '2027年度：4月入学申请期2026-08-03起至09-01 17:00（JST），发表2026-11-04，首期缴费截止2026-12-02；9月入学申请期2027-01-12起至02-09 17:00，发表2027-04-21，首期缴费截止2027-05-20。申请期内全程在线上传，补交材料与线上推荐信须在截止前由推荐人提交；审查后发送视频面试录音邀请，在指定时期内完成。一名学生每轮只能选择第一年入学或第三年插班其中之一。', 'ILA每年招约50名新生；4月与9月入学两轮受理中；转学名额有限需先邮件确认。', 'https://ila.doshisha.ac.jp/ila/en/admissions/', '["全英文LLM BA","每年约50名","三方向集中","视频面试","4月/9月双模式"]'::jsonb, '[{"name":"Institute for the Liberal Arts（ILA）国际教养 BA","level":"undergraduate","description":"全部以英语授课的文理学位；分三个反思会集中（Japanese Society and Global Culture、Japanese Business and the Global Economy、Japanese Politics and Global Studies），各集中挂靠六个学部，以成绩优先分派，入学后不可变更。","features":["英语授课","每年约50名","三方向集中","入学后不改集中"]}]'::jsonb, '["全英文讲授学位","国际教养探索","京都体验"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'tus', '东京理科大学', '東京理科大学', 'private', '理工系私立最高峰', '东京都新宿区/野田市', '2027届学部新生首年费用按学科为1,458,740–2,529,740日元；工学部多数专业为1,914,740日元。具体金额须按志望学科的官方学费表确认。', '2027要项未设全校统一GPA门槛；资格和材料按志望学部确认。', '2027学部留学生入试全部以日语授课；理工类通常要求EJU日语、数学Course 2及按学科指定的理科科目，具体组合依学部而异。', '须提交TOEFL iBT或TOEIC L&R；2027要项未公布全校统一合格分数线。', '2027学部外国留学生选拔分I/II期，以书类、EJU及面试或口头试问综合评定；II期部分学部仅书类审查。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', '2027学部外国留学生入试分I/II期：书类、EJU及面试或口头试问综合评定；II期部分学部仅书类审查。检定费35,000日元，另收1,380日元手续费。', NULL, 'https://www.tus.ac.jp/admissions/university/list/foreignstudents/index.html', '["2027学部留学生选拔","I/II期","EJU","日语授课"]'::jsonb, '[{"name":"学部外国留学生入学考试","level":"undergraduate","description":"2027年度I/II期；书类、EJU和面试或口头试问综合评定（II期部分学部为书类审查）。各学部的科目与资格须以官方要项为准。","features":["I/II期","EJU","学部别要求"]}]'::jsonb, '["理工科志向","数学/物理","私立理工最上位"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'shibaura', '芝浦工业大学', '芝浦工業大学', 'private', '私立理工系4大', '东京都江东区/埼玉县', 'IGP英语工程学本科2027秋季入学首年标准费用合计1,857,020日元；持“留学”在留资格者可免后援会相关40,000日元。', '2027 IGP要项未设统一GPA门槛；须具备高中数学，以及物理或化学至少一门的学习背景。', 'IGP为英语授课；申请不要求EJU或日语成绩。', 'IELTS 6.0+；或TOEFL iBT 79+（2026-01-20前旧量表）/4.0+（2026-01-21起新1–6量表）。', 'IGP为全英文工程学学士，2027年9月入学预计9名；前两年共同基础，之后选择五个工程方向。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', 'IGP 2027秋季两轮申请：第一轮2026-10-19至11-02，第二轮2027-02-15至03-06；2027年9月入学。申请费35,000日元。', NULL, 'https://www.igp.shibaura-it.ac.jp/', '["英语授课","2027年9月入学","预计9名","无需EJU或日语成绩"]'::jsonb, '[{"name":"Innovative Global Program（IGP）工程学学士","level":"undergraduate","description":"全英文工程学本科；前两年共同基础，之后选择机械、化学材料、电气电子、计算机通信或土木工程方向。","features":["英语授课","五个工程方向","秋季入学"]}]'::jsonb, '["理工科志向","建筑学方向","东京都心"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'denki', '东京电机大学', '東京電機大学', 'private', '理工系私立', '东京都足立区/埼玉县', '2027届首年：系统设计、工学、未来科学的信息媒体与机器人专业1,775,160日元；未来科学建筑专业1,816,160日元；理工学部1,735,160日元。持“留学”在留资格者另收年度100,000日元。', '2027要项未设统一GPA门槛；须按志望学科满足学历与EJU资格。', '该特别选拔全部以日语作答；须有足够日语能力，并提交EJU日语及数学Course 2（日语与数学合计370/600以上，数学至少120）。', '2027该学部特别选拔以日语EJU与数学为核心，英语成绩要求须按志望学科和官方要项确认。', '2027学部外国人留学生特别选拔涵盖系统设计、未来科学、工学与理工学部；每人仅可报考一个学科/学系。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', '2027学部外国人留学生特别选拔：2026-08-21至08-24出愿，09-26考试，10-05公布结果；报名时须已持“留学”在留资格。检定费35,000日元。', NULL, 'https://www.dendai.ac.jp/about/admission/undergraduate/ryugakusei.html', '["2027学部特别选拔","日语作答","EJU日语及数学","仅限一个志愿"]'::jsonb, '[{"name":"学部外国人留学生特别选拔","level":"undergraduate","description":"覆盖系统设计、未来科学、工学和理工学部的指定学科/学系；每人仅能报考一个志愿。","features":["EJU日语","数学Course 2","日语作答"]}]'::jsonb, '["机器人工程方向","实学重视","就职优先"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'aoyama', '青山学院大学', '青山学院大学', 'private', 'MARCH', '东京都涩谷区', '2027届学部入学金统一为80,000日元，设施费并入学费；在籍基本料120,000日元/年。各学部/学科首年合计不同，须按官方2027学费表逐项确认，不使用旧“约90–150万日元/年”区间。', '2027学部外国留学生选拔未设全校统一GPA门槛；资格与成绩材料依志望学部要项确认。', '2027要项未设全校统一JLPT门槛；日语和考试科目依志望学部/学科的选拔要项确认。', '2027要项未设全校统一TOEFL或IELTS门槛；外语要求依志望学部/学科确认。', '2027学部外国留学生选拔面向完成海外12年教育者，涵盖文学、教育人间科学、经济、法、经营、国际政治经济、综合文化政策、理工与社会信息等学部/学科。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', '2027学部外国留学生选拔：理工以外的资格咨询截止2026-07-21，理工学部截止2026-09-02；其余申请、考试与语言条件按志望学部要项确认。', NULL, 'https://www.aoyama.ac.jp/admission/undergraduate/examination/exam_foreign_student.html', '["2027学部留学生选拔","海外12年教育","学部别要项","费用按学科确认"]'::jsonb, '[{"name":"学部外国留学生选拔（2027）","level":"undergraduate","description":"面向完成海外12年教育者；可报文学、教育人间科学、经济、法、经营、国际政治经济、综合文化政策、理工、社会信息等指定学部/学科。","features":["海外12年教育","学部别资格","2027要项"]}]'::jsonb, '["东京都心","国际关系/政治经济","MARCH层级"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'chuo', '中央大学', '中央大学', 'private', 'MARCH', '东京都八王子市', '2027届首年费用：法学部1,413,700、经济1,375,700、商1,378,700、三理工学部各1,927,800、文1,360,700、综合政策1,680,900、国际经营1,538,300、国际信息1,631,200日元。通过外国留学生入试者免父母联络会费。', '2027要项未设全校统一GPA门槛；资格、材料与成绩依学部及选拔方式确认。', '一般资格为外国国籍、境外12年教育及指定期次EJU；EJU日语与JLPT替代的适用范围均依学部/方式而异。', '外语成绩和适用方式依学部而异；2027要项未支持全校统一TOEFL或IELTS分数线。', '2027外国留学生本科选拔覆盖法、经济、商、三理工、文、综合政策、国际经营、国际信息与体育信息等学部；EJU和外语条件按学部/方式分别规定。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', '2027外国留学生选拔检定费35,000日元，另收系统费1,350日元；例如法学部申请2026-10-26至10-30、面试2027-01-13，国际经营A方式申请2026-10-19至10-23、笔试英语和面试2026-12-05。其余日程按学部要项确认。', NULL, 'https://www.chuo-u.ac.jp/connect/admission/special/guide/', '["2027学部留学生选拔","境外12年教育","EJU","学部别外语要求"]'::jsonb, '[{"name":"学部外国留学生入学考试（2027）","level":"undergraduate","description":"覆盖法、经济、商、三理工、文、综合政策、国际经营、国际信息与体育信息等；EJU、外语和选考方式依学部/方式确定。","features":["学部别要求","EJU","外国留学生选拔"]}]'::jsonb, '["法学志向","商学/会计","MARCH层级"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'kinki', '近畿大学', '近畿大学', 'private', '私立综合', '大阪府东大阪市', '2027学费尚未由校方学费页公布；本条不以旧年度“约100–150万日元/年”作为2027报价。', '2027学部留学生要项未设全校统一GPA门槛；资格和材料依学部确认。', '理工学部留学生入试要求EJU日语、数学Course 2与理科，题目以日语出题；具体科目和条件按志望学部要项确认。', '2027学部留学生要项未公布全校统一英语成绩门槛；请按志望学部确认。', '2027学部外国人留学生入试仍实施；理工学部以材料、EJU与口头试问综合判定。', '2027起大学院不再设单独外国留学生入试；留学生参加一般入试。其他大学院资格须按研究科确认。', '2027学部外国人留学生入试：前期考试2026-10-10，后期考试2027-02-20，后期结果2027-03-09。理工学部检定费32,000日元。', NULL, 'https://www.kindai.ac.jp/campus-life/international-exchange/exam/', '["2027学部留学生入试","理工学部","EJU","日语出题"]'::jsonb, '[{"name":"学部外国人留学生入学试验（理工学部）","level":"undergraduate","description":"理工学部涵盖数学、物理、化学、生命科学、应用化学、机械、电气电子通信、社会环境及能源物质等；以材料、EJU和口头试问综合判定。","features":["EJU","口头试问","日语出题"]}]'::jsonb, '["关西综合私立","农学/水产方向","食品营养"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'nihon', '日本大学', '日本大学', 'private', '私立综合', '东京都千代田区', '2027届首年费用为学部/学科制：法学部1,260,000、经济/商各1,240,000、理工1,690,000–1,730,000、艺术1,750,000–1,950,000日元等；须按志望学部/学科的官方表确认。', '2027总要项未设全校统一GPA门槛；资格和成绩要求依学部/方式确认。', '不是全校单一门槛：法学部与国际关系学部要求JLPT N2+；艺术学部可用JLPT N2+，或指定期次EJU日语读解/听解听读解240+且记述35+。', '2027总要项未设全校统一TOEFL或IELTS门槛；外语要求依志望学部/方式确认。', '2027年4月入学外国留学生统一要项覆盖法、文理、经济、商、艺术、国际关系、体育科学、理工、生産工、工、牙、生物资源等学部；部分采用EJU，其他采用本校考试。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', '2027外国留学生统一要项按学部/方式规定；请依志望学部确认申请期、EJU或本校考试、材料与语言要求。', NULL, 'https://www.nihon-u.ac.jp/admission_info/guideline/digital_pamphlet/', '["2027年4月入学","学部别选拔","EJU或本校考试","费用按学科"]'::jsonb, '[{"name":"学部外国留学生入学试验（2027年4月）","level":"undergraduate","description":"覆盖法、文理、经济、商、艺术、国际关系、体育科学、理工、生産工、工、牙、生物资源等学部；部分采用EJU，艺术/牙/生物资源等采用本校考试。","features":["2027年4月","EJU或本校考试","学部别资格"]}]'::jsonb, '["综合私立","艺术/写真/映画","大规模大学"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'toyo', '东洋大学', '東洋大学', 'private', '首都圈私立', '东京都文京区', '2027届首年纳付金为校方“予定”：文学/经济1,265,000、国际学部1,335,000、信息连携1,675,000、理工1,690,000、环境创新1,730,000、生命科学1,715,000日元等；以最终要项为准。', '2027在线入试要项未设全校统一GPA门槛；资格与成绩材料依轨道和志望学部确认。', 'Type B为日语轨道，日语要求依志望学部确认；Type A为英语轨道，但国际地域学科Global Track仍含日语科目，不能视为全程纯英语课程。', 'Type A英语轨道：TOEFL iBT 79+（2026-01-20前旧量表）或4.5+（2026-01-21起新量表）、IELTS 6.0+或TOEIC L&R 780+。', '2027年4月外国留学生在线入试分Type A英语轨道与Type B日语轨道，可在境外线上完成选拔；Type A涵盖国际学部全球创新与国际地域学科Global Track等。', '研究生制度以目标研究科官网要项为准；本校受理研究生的研究科范围、是否需要教授内诺等条件尚未逐科核实。', '2027年4月在线入试Type A申请2026-09-22至09-25，文件审查/必要时在线面试，2026-11-22公布结果，入学手续截止12-11；申请费10,000日元。Type B按官方要项确认。', NULL, 'https://www.toyo.ac.jp/nyushi/international-student/', '["2027年4月","在线入试","Type A英语轨道","Type B日语轨道"]'::jsonb, '[{"name":"Type A 英语轨道（2027年4月）","level":"undergraduate","description":"外国留学生在线入试英语轨道；包括国际学部全球创新和国际地域学科Global Track等，具体课程结构以学部要项为准。","features":["英语成绩要求","线上选拔","2027年4月"]},{"name":"Type B 日语轨道（2027年4月）","level":"undergraduate","description":"外国留学生在线入试日语轨道；日语、科目和资格要求依志望学部确认。","features":["日语轨道","线上选拔","学部别要求"]}]'::jsonb, '["首都圈私立","国际学/观光","留学生友好"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
