INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES (
  'hal', 'HAL专门学校（东京校）', 'HAL専門学校（HAL東京）', 'IT / 游戏 / 动漫 / 设计', '东京（另有HAL大阪、HAL名古屋）', '官网HAL东京2027年度：2年制学科首年1,403,000日元（授课880,000＋教育充实费186,000＋设施设备维持费337,000），4年制首年1,463,000日元（授课940,000＋186,000＋337,000），另收入学金300,000日元。', '以官网2027年度首年额推算2年制约2,806,000日元（不含入学金与后续年度调整）；4年制另计', '官网自述为日本最大级专门学校，东京・大阪・名古屋三校约8,600名学生；与任天堂有教育提携、与Microsoft等企业连携。留学生来自43个国家和地区共982名（2025年1月时点）。', '未核实（本批未取得官方统计口径）', '官网仅列留学生就职企业例（任天堂、SEGA、CAPCOM、SQUARE ENIX、BANDAI NAMCO Studios等），未公开可核对的就业率数字，旧“近100%”表述已删除。', '入学金先纳，之后按校方指定期限缴纳年间学费；官网写明年间学费为全额一次缴纳。', '2年制授予「专门士」，4年制授予「高度专门士」（官网明记，高度专门士可获大学院入学资格）', '本批未核实官方对在留资格维持的具体出勤率门槛；旧“出勤率80%”表述无官方依据，已删除。', '["1984年大阪开校，东京・大阪・名古屋三校","任天堂教育提携、Microsoft等企业连携","游戏・CG映像・音乐・汽车设计・AI/WEB/IT分野","4年制授予高度专门士，2年制授予专门士","职业实践专门课程认定校"]'::jsonb, '[{"name":"游戏4年制／游戏2年制","description":"HAL东京2027年度首年分别为1,463,000日元与1,403,000日元（不含入学金）。","duration":"4年／2年","totalCost":"首年1,463,000／1,403,000日元"},{"name":"CG・设计・动画4年制／CG2年制","description":"3DCG、设计、动画方向，4年制授予高度专门士。","duration":"4年／2年","totalCost":"首年1,463,000／1,403,000日元"},{"name":"音乐4年制／音乐2年制","description":"音乐制作方向。","duration":"4年／2年","totalCost":"首年1,463,000／1,403,000日元"},{"name":"汽车设计4年制","description":"汽车设计方向。","duration":"4年","totalCost":"首年1,463,000日元"},{"name":"高度信息4年制／信息处理・WEB2年制","description":"AI、系统架构、WEB开发方向。","duration":"4年／2年","totalCost":"首年1,463,000／1,403,000日元"},{"name":"国家资格1年制","description":"首年956,000日元（授课700,000＋教育充实186,000＋设施70,000），入学金50,000日元。","duration":"1年","totalCost":"首年956,000日元"}]'::jsonb, '{"enrollmentFee":"入学金300,000日元（国家资格学科、巴黎校留学课程为50,000日元）","admissionFee":"官网未单列选考料；入学金于入学手续时先纳","annualTuition":"2年制授课费880,000日元／4年制940,000日元（2027年度，HAL东京）","facilitiesFee":"设施设备维持费337,000日元","practiceMaterialsFee":"教育充实费186,000日元","totalFirstYear":"2年制1,403,000日元／4年制1,463,000日元（不含入学金）"}'::jsonb, '["游戏/IT方向","希望产学连携环境","可接受较高首年费用"]'::jsonb, '["HAL提携企业学费免除制度、梦を梦で终わらせない支援金、HAL会奖学金（官网列示，金额与条件待确认）","JASSO等外部奖学金需按各制度条件确认"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
