INSERT INTO "LanguageSchool" (slug, "name", "nameJa", "location", "tuition", "paymentTerm", "attendanceRequirement", "duration", "visaRequirement", "minimumStudyForVocational", "intake", "highlights", "website", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'isi', 'ISI日本语学校', 'ISI日本語学校', '新宿本校/新宿Prime/池袋/高田马场/涩谷原宿（东京校区）', '首年101.5万～111.5万日元（东京，2027–2028）', '支持半年付（部分校区）', '90%安全线 / 80%在留更新底线', '1年～2年', '需JLPT N5或同等证书', '需在籍1年以上', '1月/4月/7月/10月', '提供升学日语与职业日语课程，东京校区收费按2027–2028官方要项列示', 'https://sm.isi-education.com/en/long/', '["日本最大规模语言学校集团","设施豪华,国际化(欧美约30%)","升学+商务+就职一条龙","校内私塾","支持半年付"]'::jsonb, '[{"name":"升学日语（Academic Japanese）","description":"新宿本校、新宿Prime、池袋、高田马场升学校区；首年101.5万～111.5万日元，依校区确定。"},{"name":"职业日语（Career Japanese）","description":"涩谷原宿与高田马场职业校区；首年105.5万日元。"}]'::jsonb, '{"enrollmentFee":"10万日元","annualTuition":"72万～76万日元","materialsFee":"5.5万日元","otherFees":"选考料4万日元；设施管理费10万～17万日元（按校区）","totalFirstYear":"101.5万～111.5万日元（按校区与课程）"}'::jsonb, '["追求国际化环境","一站式升学/就业","东京核心区域"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "paymentTerm" = EXCLUDED."paymentTerm", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "duration" = EXCLUDED."duration", "visaRequirement" = EXCLUDED."visaRequirement", "minimumStudyForVocational" = EXCLUDED."minimumStudyForVocational", "intake" = EXCLUDED."intake", "highlights" = EXCLUDED."highlights", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson";
COMMIT;
